 $allowed=['new','contacted','completed'];$status=(string)$_POST['status'];if(in_array($status,$allowed,true)){$stmt=$pdo->prepare('UPDATE su_leads SET status=:status,updated_at=UTC_TIMESTAMP() WHERE id=:id');$stmt->execute(['status'=>$status,'id'=>(int)$_POST['lead_id']]);}header('Location: index.php');exit;
}
$filter=(string)($_GET['type']??'');$allowedTypes=['club','course','collaboration','personal_message','contact'];$sql='SELECT * FROM su_leads';$params=[];if(in_array($filter,$allowedTypes,true)){$sql.=' WHERE form_type=:type';$params['type']=$filter;}$sql.=' ORDER BY created_at DESC LIMIT 250';$stmt=$pdo->prepare($sql);$stmt->execute($params);$leads=$stmt->fetchAll();
