?><!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>פניות | Shervinah</title><link rel="stylesheet" href="admin.css"></head><body><header><strong>Shervinah · ניהול החנות</strong><a href="orders.php">הזמנות</a><a href="products.php">מוצרים ומלאי</a><a href="index.php">פניות</a><a href="email-settings.php">הגדרות מייל</a><a href="?logout=1">יציאה</a></header><main><h1>פניות מהאתר</h1><nav class="filters"><a href="index.php">הכול</a><?php foreach($allowedTypes as $type):?><a href="?type=<?=urlencode($type)?>"><?=htmlspecialchars($typeLabels[$type]??$type)?></a><?php endforeach?></nav><p><?=count($leads)?> פניות מוצגות</p><?php foreach($leads as $lead):$payload=json_decode((string)$lead['payload_json'],true)?:[];?><article><div class="meta"><strong>#<?=intval($lead['id'])?> <?=htmlspecialchars($typeLabels[$lead['form_type']]??$lead['form_type'])?></strong><span><?=htmlspecialchars($lead['created_at'])?> UTC</span><span>סטטוס: <?=htmlspecialchars($statusLabels[$lead['status']]??$lead['status'])?></span></div><dl><dt>שם</dt><dd><?=htmlspecialchars($lead['full_name'])?></dd><dt>אימייל</dt><dd><a href="mailto:<?=htmlspecialchars($lead['email'])?>"><?=htmlspecialchars($lead['email'])?></a></dd><dt>טלפון</dt><dd><?=htmlspecialchars($lead['phone'])?></dd><?php foreach($payload as $key=>$value):if(in_array($key,['email','phone','full_name','first_name'],true))continue;?><dt><?=htmlspecialchars($fieldLabels[$key]??str_replace('_',' ',$key))?></dt><dd><?=htmlspecialchars((string)$value)?></dd><?php endforeach?></dl><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['csrf'])?>"><input type="hidden" name="lead_id" value="<?=intval($lead['id'])?>"><label>עדכון סטטוס<select name="status"><option value="new" <?=$lead['status']==='new'?'selected':''?>>חדש</option><option value="contacted" <?=$lead['status']==='contacted'?'selected':''?>>נוצר קשר</option><option value="completed" <?=$lead['status']==='completed'?'selected':''?>>הושלם</option></select></label><button type="submit">שמירת סטטוס</button></form></article><?php endforeach?></main></body></html>